    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نختصر الأولى","math":"<span dir=\"ltr\" class=\"expr\">-5 + ((-2) + x) = x - 7</span>"},{"quoi":"نختصر الثانية","math":"<span dir=\"ltr\" class=\"expr\">5 - [1 - (x - -1)] = x + 5</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(x - 7) - (x + 5) = -12</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">-12 < 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x - 7 < x + 5</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نختصر الأولى","math":"<span dir=\"ltr\" class=\"expr\">2 + (9 + x) = x + 11</span>"},{"quoi":"نختصر الثانية","math":"<span dir=\"ltr\" class=\"expr\">9 - [8 - (x - -6)] = x + 7</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(x + 11) - (x + 7) = 4</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">4 > 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x + 11 > x + 7</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نختصر الأولى","math":"<span dir=\"ltr\" class=\"expr\">4 + ((-3) + x) = x + 1</span>"},{"quoi":"نختصر الثانية","math":"<span dir=\"ltr\" class=\"expr\">5 - [8 - (x - 1)] = x - 4</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(x + 1) - (x - 4) = 5</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">5 > 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x + 1 > x - 4</span>"}],
